import {MOVES} from './combat-moves.mjs';
import {EMPTY_MOVE,legalMove,learningLabel} from './move-learning.mjs';
import {profile,learnable,equippedMoves,setMoves} from './training.mjs';
import {TYPE_NAMES} from './art.mjs';
export function movePicker(lab,moveCard){const g=lab.g,key=lab.key,picker=lab.picker,slot=picker.slot,p=profile(g.state,key),d=g.poke(key),equipped=equippedMoves(d,p),available=learnable(d,p),all=new Map(d.learnset.map(m=>[m.id,m]));for(const m of available)all.set(m.id,m);for(const id of [...(d.tmMoves||[]),...(d.tutorMoves||[])])if(MOVES[id])all.set(id,MOVES[id]);let choices=[...all.values()].filter(m=>m.id!==165).sort((a,b)=>a.name.localeCompare(b.name,'fr'));const fold=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');if(picker.query){const q=fold(picker.query);choices=choices.filter(m=>fold(m.name+' '+TYPE_NAMES[m.type]).includes(q))}
 return `<header><span class="eyebrow">CAPACITÉ ${slot+1}</span><h3>Choisir une capacité</h3><button data-act="lab-picker-back">← Ses capacités</button><p>Apprentissages vérifiés · Niveaux de génération ${d.learnGeneration||9}. Les CT et les maîtres des capacités sont séparés du niveau. Lutte est automatique uniquement quand les PP sont épuisés.</p><label class="picker-search">Rechercher<input data-move-search value="${g.escape(picker.query||'')}" placeholder="Nom ou type…"></label></header><div class="visual-picker move-picker">${equipped[slot].id&&!picker.query?`<button class="visual-move" data-act="lab-slot-move" data-id="0" data-slot="${slot}" ${equipped.filter(m=>m.id).length<=1?'disabled':''}><h4>Libérer cet emplacement</h4><p>Gratuit · Garde au moins une capacité.</p></button>`:''}${choices.map(m=>{const unlocked=available.some(a=>a.id===m.id),tm=!unlocked&&d.tmMoves?.includes(m.id)&&g.state.bag['tm-'+m.id]>0,tutor=!unlocked&&!tm&&d.tutorMoves?.includes(m.id),duplicate=equipped.some((a,i)=>i!==slot&&a.id===m.id),same=equipped[slot].id===m.id,disabled=duplicate||same||!unlocked&&!tm&&!tutor||(unlocked||tutor)&&g.state.materials.heartScale<1,route=unlocked?'1 écaille cœur':tm?'Utiliser 1 CT · '+g.state.bag['tm-'+m.id]+' disponible(s)':tutor?'Maître des capacités · 1 écaille cœur':m.level?'🔒 Niveau '+m.level:'🔒 CT compatible requise';return `<article class="move-option"><button class="visual-move" data-act="lab-slot-move" data-id="${m.id}" data-slot="${slot}" ${disabled?'disabled':''}><h4>${m.name}</h4>${moveCard(m)}<small>${g.escape(learningLabel(d,m))}</small><small class="move-price">${same?'Actuellement équipée':duplicate?'Déjà équipée ailleurs':route}</small></button>${moveDetails(g,m)}</article>`}).join('')||'<p>Aucune capacité ne correspond à cette recherche.</p>'}</div>`
}
export function selectCanonicalMove(g,key,slot,id){if(!g.state.roster.includes(key)||!Number.isInteger(slot)||slot<0||slot>3)return false;const d=g.poke(key);if(id&&!legalMove(d,id))return false;const p=profile(g.state,key),old=equippedMoves(d,p).map(m=>m.id);if(old[slot]===id||id&&old.some((v,i)=>i!==slot&&v===id)||id&&!legalMove(d,id))return false;if(!id){old[slot]=0;return setMoves(g.dex,g.state,key,old)}const known=learnable(d,p).some(m=>m.id===id);if(known){old[slot]=id;return setMoves(g.dex,g.state,key,old)}const tm=d.tmMoves?.includes(id)&&g.state.bag['tm-'+id]>0,tutor=!tm&&d.tutorMoves?.includes(id);if(!tm&&!tutor||tutor&&g.state.materials.heartScale<1)return false;if(tm)g.state.bag['tm-'+id]--;else g.state.materials.heartScale--;p.taughtMoves=[...new Set([...(p.taughtMoves||[]),id])];old[slot]=id;p.moves=old;delete p.moveReviewNotice;return true}

export function moveDetails(g,m){return m.showdownDescription?`<details class="showdown-rule"><summary>Règle détaillée Showdown (anglais)</summary><p lang="en">${g.escape(m.showdownDescription)}</p></details>`:''}
